// Keys plus two in-betweens per step.
export function expandMotion(keys) {
  const out = [];
  for (let k = 0; k < keys.length; k++) {
    out.push({ angles: keys[k], key: true });
    if (k === keys.length - 1) break;
    for (const u of [1 / 3, 2 / 3]) out.push({ angles: keys[k].map((v, i) => Math.round(v + (keys[k + 1][i] - v) * u)), key: false });
  }
  return out;
}
